describe('Search Suggestions Highlighting Matching Parts', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should highlight matching part of search term in suggestions', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('/api/search');
      expect(req.body.query).to.equal('cypress');
    }).as('searchRequest');

    // Type a search term
    cy.get('[data-testid="search-input"]').type('cypress');

    // Wait for API response
    cy.wait('@searchRequest');

    // Verify suggestions are displayed
    cy.get('[data-testid="suggestions-list"]').should('be.visible');
    cy.get('[data-testid="suggestion-item"]').should('have.length.greaterThan', 0);

    // Verify the first suggestion highlights the matching part
    cy.get('[data-testid="suggestion-item"]').first().should('contain', 'cypress');
    cy.get('[data-testid="suggestion-item"]').first().should('have.css', 'background-color', 'rgba(0, 123, 255, 0.1)');

    // Verify the suggestion text is not fully highlighted
    cy.get('[data-testid="suggestion-item"]').first().should('not.have.css', 'background-color', 'rgba(0, 123, 255, 0.5)');

    // Verify other suggestions are not highlighted
    cy.get('[data-testid="suggestion-item"]').eq(1).should('not.have.css', 'background-color');

    // Verify the search input still contains the full term
    cy.get('[data-testid="search-input"]').should('contain', 'cypress');
  });

  it('should handle empty search term and display no suggestions', () => {
    // Clear the search input
    cy.get('[data-testid="search-input"]').clear();

    // Type an empty term
    cy.get('[data-testid="search-input"]').type('');

    // Wait for API response
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('/api/search');
      expect(req.body.query).to.equal('');
    }).as('emptySearchRequest');
    cy.wait('@emptySearchRequest');

    // Verify suggestions are not displayed
    cy.get('[data-testid="suggestions-list"]').should('not.exist');

    // Verify search input is still visible
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Verify no error message is displayed
    cy.get('[data-testid="no-results-message"]').should('not.exist');
  });
});
